// ~~ Generated by projen. To modify, edit the @cdktn/provider-project source.
const { execFileSync } = require("child_process");
// Optional on purpose: correct version ordering is cosmetic, and a resolution
// hiccup must not take down a task whose job is to fix the lockfile.
let semver = null;
try {
  semver = require("semver");
} catch {
  semver = null;
}

const AUDIT_LEVEL = "high";
const MINIMUM_RELEASE_AGE = "5760";

function pnpm(args, opts = {}) {
  return execFileSync("pnpm", args, {
    encoding: "utf8",
    stdio: ["ignore", "pipe", "pipe"],
    ...opts,
  });
}

// A clean audit still returns an empty advisories object and exit 0, so a missing
// one means the audit itself did not run. One row per (advisory, installed
// version) so the check after the upgrade can tell a surviving advisory from a
// different one that merely shares a package name.
function auditRows(phase) {
  let raw;
  try {
    raw = pnpm(["audit", "--audit-level", AUDIT_LEVEL, "--json"]);
  } catch (e) {
    // audit exits non-zero exactly when it finds something; stdout still has it.
    raw = e.stdout;
  }
  let advisories;
  try {
    advisories = JSON.parse(raw).advisories;
  } catch {
    advisories = undefined;
  }
  if (typeof advisories !== "object" || advisories === null) {
    // Surfaced, not swallowed -- but not fatal, or one unreadable audit would cost
    // every other bump in the run. The audit gate still fails the build. What an
    // unreadable audit means differs by phase: before the upgrade nothing was
    // refreshed, after it the outcome is simply unknown.
    console.error(
      phase === "verify"
        ? "::warning::could not read 'pnpm audit --json' after upgrading; whether the advisories were resolved is unverified"
        : "::warning::could not read 'pnpm audit --json'; flagged transitives were NOT refreshed"
    );
    return undefined;
  }
  const rows = [];
  for (const a of Object.values(advisories)) {
    if (!a || !a.module_name) continue;
    const id = a.github_advisory_id || a.url || String(a.id);
    const findings = a.findings && a.findings.length ? a.findings : [{}];
    for (const f of findings) {
      rows.push({
        name: a.module_name,
        id: id,
        version: f.version || "",
        path: (f.paths || [])[0] || "",
      });
    }
  }
  return rows;
}

function advisoryKey(r) {
  return r.name + " " + r.id;
}

// Lexicographic order puts 1.10.0 before 1.9.0, which reads as a downgrade in the
// diagnostics. Fall back to string order only for anything semver cannot parse.
function sortVersions(versions) {
  return versions.slice().sort(function (a, b) {
    if (semver && semver.valid(a) && semver.valid(b)) {
      return semver.compare(a, b);
    }
    return a < b ? -1 : a > b ? 1 : 0;
  });
}

function describe(r) {
  return (
    r.name +
    (r.version ? "@" + r.version : "") +
    " " +
    r.id +
    (r.path ? " via " + r.path : "")
  );
}

function main() {
  const before = auditRows("initial");
  // undefined means the audit was unreadable, which is not the same as clean and
  // has already been warned about.
  if (before === undefined) return;
  const names = Array.from(new Set(before.map((r) => r.name))).sort();
  if (names.length === 0) {
    console.log("no " + AUDIT_LEVEL + "+ advisories to resolve");
    return;
  }

  console.log("attempting to resolve advisories in: " + names.join(", "));
  let attempted = true;
  try {
    // --depth Infinity is what lets a transitive package be named at all. stderr is
    // captured rather than inherited so the failure below can be classified; it is
    // echoed back out on failure, and stdout still streams live.
    pnpm(
      [
        "update",
        ...names,
        "--depth",
        "Infinity",
        "--config.minimum-release-age=" + MINIMUM_RELEASE_AGE,
      ],
      { stdio: ["ignore", "inherit", "pipe"] }
    );
  } catch (e) {
    // Non-fatal either way: failing here would cost every other bump in the run.
    // But registry, auth and config failures throw too, so only call it a cooldown
    // refusal when pnpm actually said so.
    const stderr = String((e && e.stderr) || "");
    if (stderr) console.error(stderr);
    console.error(
      stderr.indexOf("ERR_PNPM_NO_MATURE_MATCHING_VERSION") !== -1
        ? "::warning::" +
            names.join(", ") +
            " has no patch older than the cooldown; lockfile unchanged"
        : "::warning::could not upgrade " +
            names.join(", ") +
            "; lockfile unchanged -- see the pnpm output above"
    );
    attempted = false;
  }

  // A zero exit from the upgrade does not mean the advisory went away -- pnpm exits
  // 0 having changed nothing whenever it has nowhere in range to move to, which is
  // indistinguishable from a fix in the log. follow-redirects
  // GHSA-q3jh-wrc6-jgq8 sat on all 32 provider repos that way.
  //
  // Re-audit and report only what the audit shows. Deliberately no root cause: the
  // audit says which advisory, version and path survived, not why the solver kept
  // it, and guessing between a stale published range, an override and a second
  // installed copy would send whoever reads this to the wrong place.
  if (!attempted) return;
  const after = auditRows("verify");
  if (after === undefined) return;

  // Classify on advisory identity -- package plus advisory -- and treat the
  // installed version as movement rather than identity. The same advisory reported
  // against a newer but still-vulnerable version has not been resolved, it has
  // moved, and calling that "newly flagged" would be wrong. All three categories
  // are reported: a surviving advisory does not hide a genuinely new one.
  const versionsBefore = new Map();
  for (const r of before) {
    const k = advisoryKey(r);
    if (!versionsBefore.has(k)) versionsBefore.set(k, new Set());
    versionsBefore.get(k).add(r.version);
  }

  const unmoved = [];
  const moved = [];
  const fresh = [];
  const unversioned = [];
  for (const r of after) {
    const seen = versionsBefore.get(advisoryKey(r));
    if (!seen) {
      fresh.push(r);
      continue;
    }
    // An advisory carrying no findings reports no installed version. Comparing that
    // against a real version on the other pass would invent movement that did not
    // happen, so claim only that it is still flagged.
    if (!r.version || seen.has("")) {
      unversioned.push(r);
      continue;
    }
    if (seen.has(r.version)) unmoved.push(r);
    else moved.push({ row: r, from: sortVersions(Array.from(seen)).join(", ") });
  }

  for (const r of unmoved) {
    console.error("::warning::still flagged, not moved: " + describe(r));
  }
  for (const m of moved) {
    console.error(
      "::warning::still flagged after moving from " +
        m.from +
        ": " +
        describe(m.row)
    );
  }
  for (const r of unversioned) {
    console.error(
      "::warning::still flagged, no installed version reported: " + describe(r)
    );
  }
  for (const r of fresh) {
    console.error("::warning::newly flagged after upgrading: " + describe(r));
  }
  if (
    unmoved.length + moved.length + fresh.length + unversioned.length >
    0
  ) {
    console.error("inspect the advisories and dependency paths above");
    return;
  }
  console.log("resolved: " + names.join(", "));
}

main();
